using System;using UnityEditor;using UnityEngine;
namespace XuanwuTools { public static class TerrainPathBuilder {
 [MenuItem(Common.Menu+"03 Shape terrain from route JSON")] public static void Build()=>Common.Run(()=>{var r=Common.Read<Route>();Common.SceneGuard(r.scenePath);Common.RouteCheck(r);var t=Common.SelectedTerrain();var src=t.terrainData;var o=t.transform.position;var size=src.size;int n=src.heightmapResolution;if(n>2049)throw new Exception("Use a smaller tile; max 2049 in this tool");if(t.transform.rotation!=Quaternion.identity||t.transform.lossyScale!=Vector3.one)throw new Exception("Terrain transform must be identity scale/rotation");if(r.protectedAreas==null)throw new Exception("Explicit protectedAreas required (empty only after review)");var h=src.GetHeights(0,0,n,n);int changes=0;for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=o+new Vector3(x*size.x/(n-1),0,z*size.z/(n-1));if(Common.Protected(p,r.protectedAreas))continue;float d=Common.Nearest(p,r.points,out float y);if(d>r.halfWidth+r.shoulder)continue;float blend=d<=r.halfWidth?1:1-Mathf.SmoothStep(0,1,(d-r.halfWidth)/Mathf.Max(.001f,r.shoulder));float target=(y-o.y)/size.y;if(target<0||target>1)throw new Exception("Route outside height range");float val=Mathf.Lerp(h[z,x],target,blend);if(Mathf.Abs(val-h[z,x])>.000001f){h[z,x]=val;changes++;}}if(changes==0){Debug.Log("No terrain changes");return;}if(!Common.Confirm("Terrain dry-run",$"{changes} samples; clone TerrainData first. Protected areas not modified. Check route does not bridge chasms."))return;var data=Common.CloneData(t);data.SetHeightsDelayLOD(0,0,h);data.SyncHeightmap();EditorUtility.SetDirty(data);AssetDatabase.SaveAssetIfDirty(data);Common.Report("terrain",$"changed={changes}; copied data={AssetDatabase.GetAssetPath(data)}; verify protected edges and Play Mode.");});}}
